type OrderMsg = { customerId: string; customerName?: string; region?: string };
type Enriched = OrderMsg & Required<Pick<OrderMsg, "customerName" | "region">>;

async function enrich(msg: OrderMsg, source: CustomerSource): Promise<Enriched> {
  const c = await source.find(msg.customerId);
  return { ...msg, customerName: c.name, region: c.region };   // provably complete
}
